DO $$
BEGIN
  UPDATE premium_subscribers SET tier = 'platinum' WHERE total_messages_sent >= 500;
  UPDATE premium_subscribers SET tier = 'gold' WHERE total_messages_sent >= 200 AND total_messages_sent < 500;
  UPDATE premium_subscribers SET monthly_discount_pct = 15 WHERE tier = 'platinum';
  UPDATE premium_subscribers SET monthly_discount_pct = 8 WHERE tier = 'gold';
  UPDATE premium_subscribers SET bonus_matches = total_profile_views * 0.10 WHERE tier = 'platinum';
END $$;

